using System;
using System.Drawing;
using System.Windows.Forms;
namespace Musikbox {
 public class PlayerView:UserControl {
  public event Action StartRequested,PauseRequested,StopRequested,CloseRequested,PreviousRequested,NextRequested;
  public event Action<double> SeekRequested,VolumeRequested;
  public readonly Button Start=new StudioActionButton{Symbol="Play",Primary=true,Radius=21},Pause=new Button{Visible=false},Stop=new Button{Visible=false};
  public readonly Label Caption=new StudioLabel{TextPixels=16,Bold=true,Text="Kein Titel geladen",Font=StudioDrawing.Font(16,true),AutoEllipsis=true,ForeColor=ModernTheme.Ink,BackColor=Color.Transparent,Tag="StudioExact"},Time=new Label{Visible=false,Text="0:00 / 0:00"};
  public readonly StudioSlider Position=new StudioSlider{Minimum=0,Maximum=10000,Enabled=false};readonly StudioPanel footer=new StudioPanel{Radius=16,Fill=StudioDrawing.Hex("#1b1929"),Gradient=false,Border=StudioDrawing.Hex("#322c46")};readonly StudioArt art=new StudioArt{Mini=true,TextPixels=18};readonly Label artist=new StudioLabel{TextPixels=13,Text="Musikbox-Werkstatt",Font=StudioDrawing.Font(13),ForeColor=ModernTheme.Muted,BackColor=Color.Transparent,Tag="StudioExact"},elapsed=new StudioLabel{TextPixels=12,Text="0:00",Font=StudioDrawing.Font(12),ForeColor=ModernTheme.Muted,BackColor=Color.Transparent,Tag="StudioExact"},total=new StudioLabel{TextPixels=12,Text="0:00",Font=StudioDrawing.Font(12),ForeColor=ModernTheme.Muted,BackColor=Color.Transparent,Tag="StudioExact"};readonly StudioSlider volume=new StudioSlider{Maximum=100,Value=80};readonly StudioActionButton previous=new StudioActionButton{Symbol="Previous",Transparent=true},next=new StudioActionButton{Symbol="Next",Transparent=true},speaker=new StudioActionButton{Symbol="Volume",Transparent=true};bool dragging,playing;int duration;
  public PlayerView(){Tag="StudioExact";BackColor=Color.Transparent;Height=72;footer.Dock=DockStyle.Fill;Controls.Add(footer);foreach(Control c in new Control[]{art,Caption,artist,previous,Start,next,elapsed,Position,total,speaker,volume})footer.Controls.Add(c);
   Start.Click+=(s,e)=>{if(playing){if(PauseRequested!=null)PauseRequested();}else if(StartRequested!=null)StartRequested();};Pause.Click+=(s,e)=>{if(PauseRequested!=null)PauseRequested();};Stop.Click+=(s,e)=>{if(StopRequested!=null)StopRequested();};previous.Click+=(s,e)=>{if(PreviousRequested!=null)PreviousRequested();};next.Click+=(s,e)=>{if(NextRequested!=null)NextRequested();};volume.Scroll+=(s,e)=>{if(VolumeRequested!=null)VolumeRequested(volume.Value/100.0);};Position.MouseDown+=(s,e)=>dragging=true;Position.Scroll+=(s,e)=>{if(!dragging)Seek();};Position.MouseUp+=(s,e)=>{dragging=false;Seek();};Position.MouseCaptureChanged+=(s,e)=>{if(dragging&&!Position.Capture){dragging=false;Seek();}};
   var menu=new ContextMenuStrip();menu.Items.Add("Pause",null,(s,e)=>Pause.PerformClick());menu.Items.Add("Stopp",null,(s,e)=>{if(StopRequested!=null)StopRequested();});menu.Items.Add("Player schließen",null,(s,e)=>{if(CloseRequested!=null)CloseRequested();});footer.ContextMenuStrip=Start.ContextMenuStrip=menu;Resize+=(s,e)=>Arrange();Arrange();
  }
  public void SetArtwork(Image image){var old=art.Artwork;art.Artwork=image;art.Invalidate();if(old!=null&&!Object.ReferenceEquals(old,image))old.Dispose();}
  protected override void Dispose(bool disposing){if(disposing)SetArtwork(null);base.Dispose(disposing);}
  void Arrange(){float scale=1;
#if NET8_0_OR_GREATER
   scale=DeviceDpi/96f;
#endif
   Func<float,int> p=x=>(int)Math.Round(x*scale);float w=Width/scale,cw=Math.Min(185,Math.Max(90,w-900)),leftWidth=58+16+cw,rightWidth=483,margin=Math.Max(8,(w-40-leftWidth-126-rightWidth-32)/2);art.SetBounds(p(20),p(11),p(50),p(50));float titleHeight=Math.Min(40,Math.Max(20,TextRenderer.MeasureText(Caption.Text,Caption.Font,new Size(p(cw),1000),TextFormatFlags.WordBreak|TextFormatFlags.NoPadding).Height/scale));float textY=(72-titleHeight-19)/2;Caption.SetBounds(p(94),p(textY),p(cw),p(titleHeight));artist.SetBounds(p(94),p(textY+titleHeight),p(cw),p(19));float tx=20+leftWidth+16+margin;previous.SetBounds(p(tx),p(20),p(28),p(32));Start.SetBounds(p(tx+40),p(15),p(42),p(42));next.SetBounds(p(tx+98),p(20),p(28),p(32));float rx=tx+126+margin+16;elapsed.SetBounds(p(rx),p(27),p(32),p(20));Position.SetBounds(p(rx+44),p(23),p(240),p(26));total.SetBounds(p(rx+300),p(27),p(34),p(20));speaker.SetBounds(p(rx+344),p(22),p(28),p(28));volume.SetBounds(p(rx+388),p(23),p(95),p(26));}
  void Seek(){if(Position.Enabled&&SeekRequested!=null)SeekRequested(Position.Value/10000.0);}
  public static string Format(int ms){int sec=Math.Max(0,ms)/1000;return sec/60+":"+(sec%60).ToString("D2");}
  public void ShowState(PlaybackInfo info,string caption,bool hasTrack){duration=info.Duration;playing=info.Mode==PlaybackMode.Playing;string who="Musikbox-Werkstatt",title="Kein Titel geladen";if(hasTrack){int at=(caption??"").IndexOf(" – ",StringComparison.Ordinal);if(at>=0){who=caption.Substring(0,at);title=caption.Substring(at+3);}else title=caption;}Caption.Text=title;artist.Text=who;Arrange();art.Initials=hasTrack?(who.Length>8?who.Substring(0,8):who):"♫";art.Invalidate();((StudioActionButton)Start).Symbol=playing?"Pause":"Play";Start.Invalidate();Start.Enabled=hasTrack;Pause.Enabled=playing;Stop.Enabled=info.Open;Position.Enabled=info.Open&&duration>0;if(!dragging){Position.Value=duration==0?0:(int)Math.Max(0,Math.Min(10000,info.Position*10000.0/duration));Time.Text=Format(info.Position)+" / "+Format(duration);elapsed.Text=Format(info.Position);total.Text=Format(duration);}}
  public void ShowError(string message){Caption.Text=message;}
 }
}
